package rod_test
import("context";"encoding/json";"fmt";"reflect";"sync";"testing";"time";"github.com/go-rod/rod";"github.com/go-rod/rod/lib/cdp";"github.com/go-rod/rod/lib/proto")
type baselineClient struct{events chan *cdp.Event;mu sync.Mutex;calls []string}
func(c *baselineClient)Event()<-chan *cdp.Event{return c.events}
func(c *baselineClient)Call(ctx context.Context,s,m string,p interface{})([]byte,error){if e:=ctx.Err();e!=nil{return nil,e};c.mu.Lock();c.calls=append(c.calls,s+":"+m);c.mu.Unlock();return []byte(`{}`),nil}
func TestBaselineOneDialog(t *testing.T){ctx,cancel:=context.WithTimeout(context.Background(),5*time.Second);defer cancel();client:=&baselineClient{events:make(chan *cdp.Event)};defer close(client.events);b:=rod.New().Context(ctx).ControlURL("").NoDefaultDevice().Client(client);if e:=b.Connect();e!=nil{t.Fatal(e)};p:=b.PageFromSession("form");wait,handle:=p.HandleDialog();data,_:=json.Marshal(proto.PageJavascriptDialogOpening{URL:"https://form.invalid/",Message:"Continue?",Type:proto.PageDialogTypeConfirm});go func(){select{case client.events<-&cdp.Event{SessionID:"form",Method:"Page.javascriptDialogOpening",Params:data}:case <-ctx.Done():}}();event:=wait();if event.Message!="Continue?"{t.Fatal(event)};if e:=handle(&proto.PageHandleJavaScriptDialog{Accept:true});e!=nil{t.Fatal(e)};client.mu.Lock();defer client.mu.Unlock();found:=false;for _,s:=range client.calls{if s=="form:Page.handleJavaScriptDialog"{found=true}};if !found{t.Fatal(client.calls)};_,available:=reflect.TypeOf(p).MethodByName("WithDialogScript");fmt.Printf("one-dialog handled=%q session=form WithDialogScript_available=%v\n",event.Message,available)}
